const trashKey='frame-studio-v1-trash';
function readTrash(){const value=JSON.parse(localStorage.getItem(trashKey)||'[]');return Array.isArray(value)?value:[];}
const deleteDialog=document.createElement('dialog');deleteDialog.innerHTML='<div class="modal-head"><h2>删除项目</h2><button id="cancelDeleteTop">✕</button></div><p id="deleteProjectName"></p><p>移入本机项目回收站，可恢复。角色、场景、提示词和生成记录会一并保留。</p><div class="modal-actions"><button id="cancelDelete">取消</button><button id="confirmDelete" style="background:#573339;color:#ffd8d8">移入回收站</button></div>';document.body.append(deleteDialog);
let projectDeleteTarget=null,projectActionBusy=false;
for(const id of ['cancelDelete','cancelDeleteTop'])document.querySelector('#'+id).onclick=()=>deleteDialog.close();
async function projectRequest(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),j=await r.json();if(!r.ok)throw Error(j.error||'项目操作失败');return j;}
async function ensureProjectSaved(){
  const identity=projectIdentity(data),deadline=Date.now()+20000;
  while(true){
    if(projectIdentity(data)!==identity)throw Error('项目已切换，请重新操作');
    if(diskConflict)throw Error('项目在其他页面已更新，当前编辑已保留在浏览器备份中；请先导出当前内容，再刷新核对后导入');
    if(Date.now()>deadline)throw Error('保存等待超时，当前内容仍保留，请稍后重试');
    if(!diskReady||diskBusy){await new Promise(resolve=>setTimeout(resolve,80));continue;}
    if(data.deleted||lastDiskData===JSON.stringify(data))return;
    await flushDisk();
    if(!diskBusy&&!diskConflict&&lastDiskData!==JSON.stringify(data))throw Error('保存未完成，请检查页面顶部的保存错误；当前内容仍保留');
  }
}
function adoptLibraryProject(result){data=result.project||{title:'未创建项目',synopsis:'导入 JSON 开始新项目，或从回收站恢复。',genre:'',style:'',ratio:'',episodes:0,duration:0,characters:[],shots:[],stages:{},deleted:true};diskRevision=result.revision||0;diskIdentity=result.project?projectIdentity(data):'';lastDiskData=JSON.stringify(data);diskConflict=false;ci=si=tab=0;browserSave();document.querySelector('#diskSaveWarning')?.remove();render();}
function askDeleteLibraryProject(p){projectDeleteTarget=p;document.querySelector('#deleteProjectName').textContent='删除「'+p.title+'」？';deleteDialog.showModal();}
document.querySelector('#confirmDelete').onclick=async()=>{if(projectActionBusy||!projectDeleteTarget)return;const b=document.querySelector('#confirmDelete');projectActionBusy=true;b.disabled=true;try{await ensureProjectSaved();const id=projectDeleteTarget.identity,result=await projectRequest('/api/project?id='+encodeURIComponent(id));await projectRequest('/api/projects',{action:'delete',id,revision:result.revision});if(id===projectIdentity(data))adoptLibraryProject(await projectRequest('/api/project'));deleteDialog.close();await refreshProjectLibrary();toast('项目已移入本机回收站，可恢复');}catch(e){toast(e.message);}finally{projectActionBusy=false;b.disabled=false;}};
const trashDialog=document.createElement('dialog');trashDialog.innerHTML='<div class="modal-head"><h2>项目回收站</h2><button id="closeTrash">✕</button></div><p class="subtle">项目保存在本机，可恢复；恢复不会替换或删除其他项目。</p><div id="trashItems"></div>';document.body.append(trashDialog);document.querySelector('#closeTrash').onclick=()=>trashDialog.close();
async function showProjectTrash(){const list=document.querySelector('#trashItems');list.textContent='正在读取…';trashDialog.showModal();try{const items=await projectRequest('/api/projects?action=trash');list.replaceChildren();if(!items.length&&!readTrash().length)list.textContent='回收站暂无项目。';for(const p of items){const row=document.createElement('div');row.className='card';row.style.marginBottom='10px';const title=document.createElement('p');title.textContent=p.title+' · '+new Date(p.deleted_at||p.saved_at).toLocaleString('zh-CN');const restore=document.createElement('button');restore.textContent='恢复项目';restore.onclick=async()=>{restore.disabled=true;try{await ensureProjectSaved();await projectRequest('/api/projects',{action:'restore',id:p.identity,revision:p.revision});if(data.deleted)adoptLibraryProject(await projectRequest('/api/project?id='+encodeURIComponent(p.identity)));await refreshProjectLibrary();trashDialog.close();toast('项目已恢复到列表');}catch(e){toast(e.message);restore.disabled=false;}};const purge=document.createElement('button');purge.textContent='彻底删除';purge.style.cssText='color:#f1b6b6;margin-left:10px';purge.onclick=()=>askPurgeProject(p,false);row.append(title,restore,purge);list.append(row);}
// Preserve access to projects saved by the older browser-only recycle bin.
for(const item of readTrash()){const row=document.createElement('div');row.className='card';const title=document.createElement('p');title.textContent=item.project.title+' · 旧浏览器回收站';const restore=document.createElement('button');restore.textContent='恢复到项目列表';restore.onclick=async()=>{restore.disabled=true;try{await ensureProjectSaved();const id=projectIdentity(item.project),existing=await projectRequest('/api/project?id='+encodeURIComponent(id));if(existing.project?.deleted)await projectRequest('/api/projects',{action:'restore',id,revision:existing.revision});else if(!existing.project)await projectRequest('/api/project',{revision:existing.revision,project:item.project});else{toast('同一项目已在列表中，未覆盖现有内容');return;}localStorage.setItem(trashKey,JSON.stringify(readTrash().filter(x=>x.id!==item.id)));await refreshProjectLibrary();trashDialog.close();toast('项目已恢复');}catch(e){toast(e.message);}finally{restore.disabled=false;}};const purge=document.createElement('button');purge.textContent='彻底删除';purge.style.cssText='color:#f1b6b6;margin-left:10px';purge.onclick=()=>askPurgeProject(item,true);row.append(title,restore,purge);list.append(row);}
}catch(e){list.textContent=e.message;}}
const mainProjectActions=document.createElement('div');mainProjectActions.style.cssText='display:flex;align-items:center;gap:14px;flex-wrap:wrap';const storyEditButton=document.querySelector('#editStory');storyEditButton.parentElement.append(mainProjectActions);mainProjectActions.append(storyEditButton);const mainTrashButton=document.createElement('button');mainTrashButton.textContent='项目回收站';mainTrashButton.className='text';mainTrashButton.onclick=showProjectTrash;mainProjectActions.append(mainTrashButton);

const projectPurgeDialog=document.createElement('dialog');projectPurgeDialog.innerHTML='<div class="modal-head"><h2>彻底删除项目</h2><button id="closeProjectPurge">✕</button></div><p id="projectPurgeName"></p><p id="projectPurgeWarning"></p><p class="subtle">已生成的图片、视频及手动导出的文件保留。</p><div class="modal-actions"><button id="cancelProjectPurge">取消</button><button id="confirmProjectPurge" style="background:#693039;color:#ffe0e0">确认彻底删除</button></div>';document.body.append(projectPurgeDialog);
let projectPurgeTarget=null,projectPurging=false;
for(const id of ['closeProjectPurge','cancelProjectPurge'])document.querySelector('#'+id).onclick=()=>{if(!projectPurging)projectPurgeDialog.close();};
function askPurgeProject(item,legacy){projectPurgeTarget={item,legacy};document.querySelector('#projectPurgeName').textContent='彻底删除「'+(legacy?item.project.title:item.title)+'」？';document.querySelector('#projectPurgeWarning').textContent=legacy?'这条旧浏览器回收站备份将永久移除，无法恢复。其他项目及磁盘中的同名项目不受影响。':'项目设定、提示词、项目内生成记录及项目保存备份将永久删除，无法从回收站恢复。';projectPurgeDialog.showModal();}
document.querySelector('#confirmProjectPurge').onclick=async()=>{if(projectPurging||!projectPurgeTarget)return;const button=document.querySelector('#confirmProjectPurge');projectPurging=true;button.disabled=true;try{const {item,legacy}=projectPurgeTarget;if(legacy){localStorage.setItem(trashKey,JSON.stringify(readTrash().filter(x=>x.id!==item.id)));}else{await projectRequest('/api/projects',{action:'purge',id:item.identity,revision:item.revision,confirm_permanent:true});for(const cacheKey of [key,'frame-studio-pre-disk-backup']){try{const cached=JSON.parse(localStorage.getItem(cacheKey)||'null');if(cached&&projectIdentity(cached)===item.identity)localStorage.removeItem(cacheKey);}catch{}}localStorage.setItem(trashKey,JSON.stringify(readTrash().filter(x=>projectIdentity(x.project)!==item.identity)));}projectPurgeDialog.close();await showProjectTrash();await refreshProjectLibrary();toast('项目已彻底删除，生成文件保留');}catch(e){toast(e.message);}finally{projectPurging=false;button.disabled=false;}};
